import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.Boholvbs.js";const u=JSON.parse('{"title":"Trial runbook: one account, all your devices","description":"","frontmatter":{},"headers":[],"relativePath":"trial.md","filePath":"trial.md"}'),n={name:"trial.md"};function o(l,e,h,p,d,r){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="trial-runbook-one-account-all-your-devices" tabindex="-1">Trial runbook: one account, all your devices <a class="header-anchor" href="#trial-runbook-one-account-all-your-devices" aria-label="Permalink to &quot;Trial runbook: one account, all your devices&quot;">​</a></h1><p>What it takes to run the private trial end to end — relay, phone, computers, web — from a clean VPS to &quot;the phone tells the Mac to build the project&quot;. Everything here is in the private <code>nanomuse-trial</code> repository (branch <code>trial</code>) until it ships in the public one.</p><h2 id="_0-what-you-need" tabindex="-1">0. What you need <a class="header-anchor" href="#_0-what-you-need" aria-label="Permalink to &quot;0. What you need&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>for</th></tr></thead><tbody><tr><td>A small Linux VPS with Docker (1 vCPU / 1 GB is plenty) and a domain name pointed at it, e.g. <code>cloud.example.com</code></td><td>the relay + hub + web console</td></tr><tr><td>An OpenAI-compatible model key — Alibaba Model Studio (百炼) by default; the same key serves pictures</td><td>what the Muses think with</td></tr><tr><td>A way to send codes: SMTP credentials (e-mail sign-in) and/or Aliyun SMS (mainland numbers) — or <code>CODE_SENDER=log</code> and read codes from the server log while it is only you</td><td>sign-in</td></tr><tr><td>Android phone: the arm64 debug APK from <code>./gradlew :app:assembleDebug</code> (sideload)</td><td>the phone&#39;s Muse</td></tr><tr><td>Computers: the installer for each from the <code>desktop</code> workflow artifacts — <em>Actions → desktop → Run workflow</em> builds all four (Windows <code>-setup.exe</code>, macOS <code>.pkg</code> for Apple silicon and Intel, Linux <code>.deb</code>); a <code>desktop-v*</code> tag also publishes them as a release</td><td>the computers&#39; Muses</td></tr><tr><td>iPhone (optional): TestFlight through the <code>ios-testflight</code> workflow — needs an Apple Developer account and App Store Connect API key in the repo secrets; run <em>iOS · build check</em> first, it needs neither</td><td>the iPhone on the hub (it answers <code>info</code>, <code>open</code>, <code>notify</code>; shell, files and tasks on the iPhone are still to come)</td></tr></tbody></table><h2 id="_1-the-relay" tabindex="-1">1. The relay <a class="header-anchor" href="#_1-the-relay" aria-label="Permalink to &quot;1. The relay&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:nano-muse/nanomuse-trial.git</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nanomuse-trial/cloud</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>Fill <code>.env</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CLOUD_DOMAIN=cloud.example.com</span></span>
<span class="line"><span>PUBLIC_BASE=https://cloud.example.com</span></span>
<span class="line"><span>CLOUD_SECRET=&lt;openssl rand -hex 32&gt;        # back it up with data/: rotating it orphans accounts</span></span>
<span class="line"><span>CLOUD_ADMIN_TOKEN=&lt;openssl rand -hex 32&gt;</span></span>
<span class="line"><span>UPSTREAM_BASE=…/compatible-mode/v1          # your Model Studio endpoint</span></span>
<span class="line"><span>UPSTREAM_KEY=sk-…</span></span>
<span class="line"><span>DASHSCOPE_BASE=…/api/v1</span></span>
<span class="line"><span>SIGNUP_OPEN=0                               # members only while you try it; 1 opens sign-up</span></span>
<span class="line"><span>ALLOWED_IDENTIFIERS=139xxxxxxxx, you@example.com   # members: no daily cap</span></span>
<span class="line"><span>DAILY_CAP_CNY=25                            # yuan a day for everyone else once sign-up is open</span></span>
<span class="line"><span>CODE_SENDER=smtp                            # or aliyun / both / log</span></span>
<span class="line"><span>SMTP_HOST=… SMTP_PORT=465 SMTP_USER=… SMTP_PASSWORD=… SMTP_FROM=nanoMuse &lt;no-reply@example.com&gt;</span></span>
<span class="line"><span>HUB_ENABLED=true</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # relay on :8787 behind Caddy, which fetches the certificate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> relay</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # codes appear here when CODE_SENDER=log</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://cloud.example.com/healthz</span></span></code></pre></div><p>The web console is at <code>https://cloud.example.com/app/</code>, the operator&#39;s page at <code>/app/admin/</code> (asks for <code>CLOUD_ADMIN_TOKEN</code>: who signed in, usage, devices, grant / disable / delete). Data (SQLite) lives in <code>cloud/data/</code>; back it up together with <code>CLOUD_SECRET</code>. Tokens have no ceiling by default; the daily money cap (<code>DAILY_CAP_CNY</code>) is what limits an account, and members escape it.</p><p>The production relay, <code>https://cloud.nanomuse.cn</code>, is this same code on the box that serves nanomuse.cn, behind the showcase&#39;s Caddy; <a href="https://github.com/nano-muse/nanoMuse/blob/main/cloud/deploy/nanomuse-hk/README.md" target="_blank" rel="noreferrer"><code>cloud/deploy/nanomuse-hk/</code></a> has the compose file, the Caddy site, the backup timer and the deploy script.</p><h2 id="_2-the-phone" tabindex="-1">2. The phone <a class="header-anchor" href="#_2-the-phone" aria-label="Permalink to &quot;2. The phone&quot;">​</a></h2><p>Install the APK. On the first screen, <em>接入模型</em> → your number or address → the code → done: the nanoMuse Cloud provider, a default model group, and the hub connection are set up in one go. (A debug build shows the <em>中转服务器</em> field; type your relay&#39;s address there. Release builds use the default relay.)</p><p><em>Settings → nanoMuse Cloud</em> now has a <strong>Devices</strong> section: the two switches (reachable · operable), the phone&#39;s name (rename it to something you will say out loud — &quot;pixel&quot;, &quot;小米&quot;), the other devices, and the console link. A quiet notification shows while the phone is on the hub.</p><h2 id="_3-the-computers" tabindex="-1">3. The computers <a class="header-anchor" href="#_3-the-computers" aria-label="Permalink to &quot;3. The computers&quot;">​</a></h2><p>Install the package. Then, in a terminal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nanomuse-desktop</span></span></code></pre></div><p>Server → number or address → code. Name the computer (<code>nanomuse-desktop rename mac</code>). <code>nanomuse-desktop run --open</code> chats in the terminal and opens the console; <code>nanomuse-desktop serve</code> keeps it reachable without a chat (put it in a login item / systemd user service / Task Scheduler if you want it always on).</p><h2 id="_4-try-it" tabindex="-1">4. Try it <a class="header-anchor" href="#_4-try-it" aria-label="Permalink to &quot;4. Try it&quot;">​</a></h2><p>On the phone: 「在 mac 上列一下下载文件夹」 「让 desk 把 ~/proj 编译一遍，把最后二十行日志发我」 「电脑截个图给我看」 「给电脑发个通知：该睡了」</p><p>On the computer: &quot;on the phone, take a screenshot&quot;, &quot;tell pixel&#39;s Muse to read me the last notification&quot;, &quot;send pixel a notification: build finished&quot;.</p><p>In the console: pick a device, type; approvals show as cards.</p><p>Anything that deletes, sends, pays or touches the system asks first — on the device where you typed it. A remote Muse&#39;s approval question comes back to you the same way.</p><h2 id="_5-operating" tabindex="-1">5. Operating <a class="header-anchor" href="#_5-operating" aria-label="Permalink to &quot;5. Operating&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># accounts (hints only, never identifiers) and allowance</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-Admin-Token: </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CLOUD_ADMIN_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://cloud.example.com/v1/admin/accounts</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># top up</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-Admin-Token: </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CLOUD_ADMIN_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://cloud.example.com/v1/admin/grant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;content-type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;identifier&quot;:&quot;139…&quot;,&quot;tokens&quot;:1000000}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># who is on the hub (with a device&#39;s own key)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer nm_…&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://cloud.example.com/v1/devices</span></span></code></pre></div><p>Letting someone else in: <code>SIGNUP_OPEN=1</code> and <code>docker compose up -d</code> again lets anyone register with the daily cap; <em>设为成员</em> on the admin page, or a line in <code>ALLOWED_IDENTIFIERS</code>, lifts the cap for one person.</p><h2 id="_6-where-it-stands" tabindex="-1">6. Where it stands <a class="header-anchor" href="#_6-where-it-stands" aria-label="Permalink to &quot;6. Where it stands&quot;">​</a></h2><p>Verified on the development machine: relay + hub, Linux desktop, Android emulator and the web console on one account — phone→PC (<code>devices</code>, <code>run</code>, <code>ls</code>, <code>notify</code>, <code>task</code>), PC→phone (<code>info</code>, <code>notify</code>, <code>task</code>, natural-language notify + delegate), web→phone and web→PC (tasks, approval cards), rename and forget (also from the console). The macOS and Windows packages come out of CI (the <code>desktop</code> workflow, all four targets green) and were not run on real machines here. The iOS side — sign-in and the hub client — is written without a Mac; the <code>ios-check</code> workflow is the compile test, the <code>ios-testflight</code> workflow the delivery. Shell and files on the phone use the Linux sandbox, which exists on arm64 phones (the emulator build has none).</p>`,28)])])}const k=s(n,[["render",o]]);export{u as __pageData,k as default};
